    fn from(error: RecordLogError) -> Self {
        Self::Storage(error)
    }
}

impl From<DeltaError> for SpoolError {
    fn from(error: DeltaError) -> Self {
        match error {
            DeltaError::InvalidLimit => Self::Limit,
            DeltaError::OrdinalExhausted => Self::CounterExhausted,
